CREATE OR REPLACE FUNCTION public.anonymize_user_account(target_user_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'pg_catalog', 'pg_temp'
AS $function$
begin
  if auth.uid() is distinct from target_user_id then
    raise exception using
      errcode = '42501',
      message = 'Can only anonymize your own account';
  end if;

  if exists (
    select 1
    from public.company_memberships membership
    join public.companies company on company.id = membership.company_id
    where membership.user_id = target_user_id
      and coalesce(membership.status, 'active') = 'active'
      and coalesce(
        nullif(lower(membership.membership_role), ''),
        nullif(lower(membership.role), ''),
        nullif(lower(membership.role_key), '')
      ) = 'owner'
      and company.archived_at is null
  ) then
    raise exception using
      errcode = 'P0001',
      message = 'Active companies must be transferred or archived first';
  end if;

  if to_regclass('public.user_preferences') is not null then
    execute 'delete from public.user_preferences where user_id = $1'
      using target_user_id;
  end if;
  if to_regclass('public.user_permission_overrides') is not null then
    execute 'delete from public.user_permission_overrides where user_id = $1'
      using target_user_id;
  end if;
  if to_regclass('public.user_roles') is not null then
    execute 'delete from public.user_roles where user_id = $1'
      using target_user_id;
  end if;
  if to_regclass('public.company_memberships') is not null then
    execute 'delete from public.company_memberships where user_id = $1'
      using target_user_id;
  end if;
  if to_regclass('public.agency_members') is not null then
    execute 'delete from public.agency_members where user_id = $1'
      using target_user_id;
  end if;
  if to_regclass('public.team_members') is not null then
    execute 'delete from public.team_members where user_id = $1'
      using target_user_id;
  end if;
  if to_regclass('public.bankid_enrichment') is not null then
    execute 'delete from public.bankid_enrichment where user_id = $1'
      using target_user_id;
  end if;
  if to_regclass('public.extension_data') is not null then
    execute
      'delete from public.extension_data where user_id = $1 and key = ''bankid_enrichment'''
      using target_user_id;
  end if;

  if to_regclass('public.company_invitations') is not null
     and exists (
       select 1 from information_schema.columns
       where table_schema = 'public'
         and table_name = 'company_invitations'
         and column_name = 'invited_user_id'
     ) then
    if exists (
      select 1 from information_schema.columns
      where table_schema = 'public'
        and table_name = 'company_invitations'
        and column_name = 'invited_user_id'
        and is_nullable = 'YES'
    ) then
      execute 'update public.company_invitations set invited_user_id = null where invited_user_id = $1'
        using target_user_id;
    else
      execute 'delete from public.company_invitations where invited_user_id = $1'
        using target_user_id;
    end if;
  end if;

  if to_regclass('auth.sessions') is not null then
    execute 'delete from auth.sessions where user_id = $1'
      using target_user_id;
  end if;
  if to_regclass('auth.refresh_tokens') is not null
     and exists (
       select 1 from information_schema.columns
       where table_schema = 'auth'
         and table_name = 'refresh_tokens'
         and column_name = 'user_id'
     ) then
    execute 'delete from auth.refresh_tokens where user_id::text = $1::text'
      using target_user_id;
  end if;

  update public.user_profiles
  set email = null,
      full_name = null,
      phone = null,
      user_status = 'disabled',
      active_company_id = null,
      updated_at = now()
  where id = target_user_id;
end
$function$

CREATE OR REPLACE FUNCTION public.gridex_create_supplier_switch_v1(p_company_id uuid, p_request jsonb, p_event jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_catalog', 'pg_temp'
AS $function$
declare
  v_row public.supplier_switch_requests%rowtype;
  v_existing public.supplier_switch_requests%rowtype;
  v_key text := nullif(p_request->>'automation_key', '');
  v_payload jsonb;
  v_columns text;
begin
  perform public.gridex_assert_switch_writer_v1(p_company_id);

  if v_key is not null then
    select * into v_existing
    from public.supplier_switch_requests
    where company_id = p_company_id
      and automation_key = v_key
      and status in ('draft', 'queued', 'submitted', 'accepted', 'cancellation_requested',
        'cancellation_sent', 'manual_followup_required', 'pending', 'ready', 'prepared',
        'in_progress', 'sent', 'waiting_response', 'awaiting_confirmation', 'confirmed')
    limit 1;
    if found then
      return jsonb_build_object('request', to_jsonb(v_existing), 'existing', true);
    end if;
  end if;

  v_payload := (p_request - 'company_id') || jsonb_build_object('company_id', p_company_id);
  select string_agg(quote_ident(key), ', ' order by key) into v_columns
  from jsonb_object_keys(v_payload) as key
  where key in (
    select attname from pg_attribute
    where attrelid = 'public.supplier_switch_requests'::regclass and attnum > 0 and not attisdropped
  );
  execute format(
    'insert into public.supplier_switch_requests (%1$s) select %1$s from jsonb_populate_record(null::public.supplier_switch_requests, $1) returning *',
    v_columns
  ) into v_row using v_payload;

  insert into public.supplier_switch_events (
    switch_request_id, event_type, event_status, message, payload, company_id, created_by
  ) values (
    v_row.id,
    coalesce(p_event->>'event_type', 'created'),
    coalesce(p_event->>'event_status', 'success'),
    p_event->>'message',
    coalesce(p_event->'payload', '{}'::jsonb),
    p_company_id,
    nullif(p_event->>'created_by', '')::uuid
  );

  return jsonb_build_object('request', to_jsonb(v_row), 'existing', false);
end
$function$

CREATE OR REPLACE FUNCTION public.gridex_db4b_archive_customer_registry_row(p_lookup text, p_email text DEFAULT NULL::text, p_apply boolean DEFAULT false, p_reason text DEFAULT 'Archived old/test customer from active customer registry.'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'pg_catalog', 'pg_temp'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_customer_count integer := 0;
  v_updated_customers integer := 0;
begin
  if nullif(btrim(coalesce(p_lookup, '')), '') is null
     and nullif(btrim(coalesce(p_email, '')), '') is null then
    raise exception using
      errcode = '22023',
      message = 'p_lookup or p_email is required';
  end if;

  select count(*) into v_customer_count
  from public.customers customer
  where (
    p_lookup is not null
    and (
      customer.id::text = p_lookup
      or customer.customer_number = p_lookup
      or customer.personal_number = p_lookup
    )
  ) or (
    p_email is not null
    and lower(coalesce(customer.email, '')) = lower(p_email)
  );

  if not p_apply then
    return jsonb_build_object(
      'apply', false,
      'matched_customers', v_customer_count,
      'matched_customer_profiles', 0,
      'message', 'Dry-run only. Re-run with p_apply=true to archive matching canonical customer rows.'
    );
  end if;

  insert into public.gridex_archived_customer_registry_rows(
    archived_by, archive_reason, source_table, source_id, source_email, source_row
  )
  select
    v_actor, p_reason, 'customers', customer.id::text, customer.email,
    to_jsonb(customer)
  from public.customers customer
  where (
    p_lookup is not null
    and (
      customer.id::text = p_lookup
      or customer.customer_number = p_lookup
      or customer.personal_number = p_lookup
    )
  ) or (
    p_email is not null
    and lower(coalesce(customer.email, '')) = lower(p_email)
  );

  update public.customers customer
  set status = 'archived',
      metadata = coalesce(customer.metadata, '{}'::jsonb) || jsonb_build_object(
        'archived_from_active_registry', true,
        'archived_at', now(),
        'archived_reason', p_reason,
        'db4b_cleanup', true
      ),
      updated_at = now(),
      updated_by = coalesce(v_actor, customer.updated_by)
  where (
    p_lookup is not null
    and (
      customer.id::text = p_lookup
      or customer.customer_number = p_lookup
      or customer.personal_number = p_lookup
    )
  ) or (
    p_email is not null
    and lower(coalesce(customer.email, '')) = lower(p_email)
  );
  get diagnostics v_updated_customers = row_count;

  return jsonb_build_object(
    'apply', true,
    'matched_customers_before_apply', v_customer_count,
    'matched_customer_profiles_before_apply', 0,
    'archived_customers', v_updated_customers,
    'removed_customer_profiles', 0,
    'message', 'Matching canonical customer rows were archived. Authentication and tenant memberships were not touched.'
  );
end
$function$

CREATE OR REPLACE FUNCTION public.gridex_finalize_supplier_switch_v1(p_company_id uuid, p_request_id uuid, p_actor_user_id uuid, p_event jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_catalog', 'pg_temp'
AS $function$
declare
  v_request public.supplier_switch_requests%rowtype;
  v_site_before public.customer_sites%rowtype;
  v_site_after public.customer_sites%rowtype;
  v_point_before public.metering_points%rowtype;
  v_point_after public.metering_points%rowtype;
begin
  perform public.gridex_assert_switch_writer_v1(p_company_id);

  select * into v_request
  from public.supplier_switch_requests
  where id = p_request_id and company_id = p_company_id
  for update;
  if not found then
    raise exception using errcode = 'P0002', message = 'supplier_switch_not_found_for_tenant';
  end if;
  if v_request.status = 'completed' then
    return jsonb_build_object('already_completed', true, 'request', to_jsonb(v_request));
  end if;
  if v_request.status <> 'accepted' or v_request.inbound_z04_message_id is null then
    raise exception using errcode = '23514', message = 'supplier_switch_finalize_requires_accepted_z04';
  end if;

  select * into v_site_before
  from public.customer_sites
  where id = v_request.site_id and company_id = p_company_id
  for update;
  if not found then
    raise exception using errcode = 'P0002', message = 'supplier_switch_site_not_found_for_tenant';
  end if;

  update public.customer_sites
  set current_supplier_name = v_request.incoming_supplier_name,
      current_supplier_org_number = v_request.incoming_supplier_org_number,
      status = case when status = 'closed' then 'closed' else 'active' end,
      grid_owner_id = coalesce(grid_owner_id, v_request.grid_owner_id),
      price_area_code = coalesce(price_area_code, v_request.price_area_code),
      updated_by = p_actor_user_id
  where id = v_site_before.id
  returning * into v_site_after;

  if v_request.metering_point_id is not null then
    select * into v_point_before
    from public.metering_points
    where id = v_request.metering_point_id and company_id = p_company_id
    for update;
    if found then
      update public.metering_points
      set status = case when status = 'closed' then 'closed' else 'active' end,
          grid_owner_id = coalesce(grid_owner_id, v_request.grid_owner_id),
          price_area_code = coalesce(price_area_code, v_request.price_area_code),
          updated_by = p_actor_user_id
      where id = v_point_before.id
      returning * into v_point_after;
    end if;
  end if;

  update public.supplier_switch_requests
  set status = 'completed', completed_at = now(), updated_by = p_actor_user_id, updated_at = now()
  where id = p_request_id
  returning * into v_request;

  insert into public.supplier_switch_events (
    switch_request_id, event_type, event_status, message, payload, company_id, created_by
  ) values (
    p_request_id,
    coalesce(p_event->>'event_type', 'execution_completed'),
    coalesce(p_event->>'event_status', 'completed'),
    p_event->>'message',
    coalesce(p_event->'payload', '{}'::jsonb) || jsonb_build_object(
      'siteStatusBefore', v_site_before.status,
      'siteStatusAfter', v_site_after.status,
      'meteringPointStatusBefore', v_point_before.status,
      'meteringPointStatusAfter', v_point_after.status
    ),
    p_company_id,
    p_actor_user_id
  );

  return jsonb_build_object(
    'already_completed', false,
    'request', to_jsonb(v_request),
    'site_before', to_jsonb(v_site_before),
    'site_after', to_jsonb(v_site_after),
    'metering_point_before', case when v_point_before.id is null then null else to_jsonb(v_point_before) end,
    'metering_point_after', case when v_point_after.id is null then null else to_jsonb(v_point_after) end
  );
end
$function$

CREATE OR REPLACE FUNCTION public.gridex_is_current_session_allowed()
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'pg_catalog', 'pg_temp'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_status text;
  v_disabled_at timestamptz;
begin
  if v_user_id is null then
    return false;
  end if;
  if to_regclass('public.user_profiles') is null then
    return true;
  end if;
  if exists(
    select 1
    from information_schema.columns
    where table_schema = 'public'
      and table_name = 'user_profiles'
      and column_name = 'disabled_at'
  ) then
    execute
      'select profile.user_status,profile.disabled_at
       from public.user_profiles profile where profile.id=$1'
    into v_status, v_disabled_at
    using v_user_id;
  else
    select profile.user_status
    into v_status
    from public.user_profiles profile
    where profile.id = v_user_id;
  end if;
  if coalesce(v_status, 'active') in (
    'disabled',
    'locked_security',
    'removed_from_company',
    'invitation_revoked'
  ) then
    return false;
  end if;
  return v_disabled_at is null;
end
$function$

CREATE OR REPLACE FUNCTION public.gridex_next_customer_number(p_company_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_prefix text;
  v_existing_next bigint;
  v_number bigint;
begin
  if p_company_id is null then
    raise exception 'company_id is required';
  end if;

  v_prefix := public.gridex_default_customer_number_prefix(p_company_id);

  if v_prefix !~ '^[A-Z0-9]{2,12}$' then
    raise exception 'invalid customer number prefix: %', v_prefix;
  end if;

  select coalesce(max(nullif(substring(customer_number from '([0-9]+)$'), '')::bigint) + 1, 100001)
    into v_existing_next
  from public.customers
  where company_id = p_company_id
    and customer_number is not null;

  insert into public.company_customer_number_sequences(company_id, prefix, next_number)
  values (p_company_id, v_prefix, v_existing_next)
  on conflict (company_id) do nothing;

  update public.company_customer_number_sequences
     set next_number = greatest(next_number, v_existing_next) + 1,
         prefix = v_prefix,
         updated_at = now()
   where company_id = p_company_id
   returning prefix, next_number - 1 into v_prefix, v_number;

  if v_number is null then
    raise exception 'customer number sequence could not be reserved';
  end if;

  return v_prefix || '-' || v_number::text;
end;
$function$

CREATE OR REPLACE FUNCTION public.gridex_transition_supplier_switch_v1(p_company_id uuid, p_request_id uuid, p_patch jsonb, p_event jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_catalog', 'pg_temp'
AS $function$
declare
  v_before public.supplier_switch_requests%rowtype;
  v_after public.supplier_switch_requests%rowtype;
  v_patch jsonb := coalesce(p_patch, '{}'::jsonb) - 'updated_at';
  v_key text;
  v_set text;
  v_allowed constant text[] := array[
    'status', 'requested_start_date', 'confirmed_start_date', 'submitted_at', 'completed_at',
    'failed_at', 'failure_reason', 'external_reference', 'validation_snapshot', 'metadata',
    'lifecycle_blocked', 'lifecycle_block_source', 'lifecycle_block_id', 'pause_reason',
    'paused_at', 'paused_by', 'inbound_z04_message_id', 'updated_by',
    'authorization_document_id', 'power_of_attorney_id', 'operation_id'
  ];
begin
  perform public.gridex_assert_switch_writer_v1(p_company_id);

  select * into v_before
  from public.supplier_switch_requests
  where id = p_request_id and company_id = p_company_id
  for update;
  if not found then
    raise exception using errcode = 'P0002', message = 'supplier_switch_not_found_for_tenant';
  end if;

  for v_key in select jsonb_object_keys(v_patch) loop
    if not v_key = any (v_allowed) then
      raise exception using errcode = '22023', message = 'supplier_switch_patch_column_not_allowed', detail = v_key;
    end if;
  end loop;

  select string_agg(format('%1$I = patch.%1$I', key), ', ')
  into v_set
  from jsonb_object_keys(v_patch) as key;
  v_set := concat_ws(', ', v_set, 'updated_at = now()');

  execute format(
    'update public.supplier_switch_requests target set %s
       from jsonb_populate_record(null::public.supplier_switch_requests, $3) as patch
      where target.id = $1 and target.company_id = $2
      returning target.*',
    v_set
  ) into v_after using p_request_id, p_company_id, v_patch;

  if p_event is not null then
    insert into public.supplier_switch_events (
      switch_request_id, event_type, event_status, message, payload, company_id, created_by
    ) values (
      p_request_id,
      coalesce(p_event->>'event_type', 'status_changed'),
      coalesce(p_event->>'event_status', 'success'),
      p_event->>'message',
      coalesce(p_event->'payload', '{}'::jsonb)
        || jsonb_build_object('previous_status', v_before.status, 'new_status', v_after.status),
      p_company_id,
      nullif(p_event->>'created_by', '')::uuid
    );
  end if;

  return jsonb_build_object('before', to_jsonb(v_before), 'request', to_jsonb(v_after));
end
$function$

